namespace NHAMBS.CoveredBonds

open System.IO
open FSharp.Data

/// Typed view of one CMHC Canadian registered covered bond program page.
///
/// The provider reads
/// `schema/cmhc-covered-bond-program.provider.schema.json`, a flattened copy of
/// the real Draft 2020-12 schema. The copy is generated by
/// `generate-provider-schemas.fsx` because FSharp.Data's schema reader does not
/// resolve `$ref`. The real schema remains the source of truth and is embedded
/// in this assembly for validation by `ProgramSchema.validate`.
type CoveredBondProgram =
    JsonProvider<
        "",
        Schema="schema/cmhc-covered-bond-program.provider.schema.json",
        EmbeddedResource="NHAMBS.CoveredBonds, NHAMBS.CoveredBonds.schema.cmhc-covered-bond-program.provider.schema.json"
     >

[<RequireQualifiedAccess>]
module CoveredBondProgram =

    /// Parse JSON that is already known to match the program schema.
    let parse (json: string) : CoveredBondProgram.Root = CoveredBondProgram.Parse json

    /// Validate JSON against the embedded program schema, then parse it.
    let parseValidated (json: string) : Result<CoveredBondProgram.Root, ValidationError list> =
        match ProgramSchema.validate json with
        | Error errors -> Error errors
        | Ok _ -> Ok(parse json)

    /// Load one program file, validate it, and return its typed representation.
    let load (path: string) : Result<CoveredBondProgram.Root, ValidationError list> =
        File.ReadAllText path |> parseValidated

    /// Load a sequence of program files. Each result keeps its source path.
    let loadMany (paths: string seq) =
        paths |> Seq.map (fun path -> path, load path) |> Seq.toArray

    /// Load every `*.json` file directly under a directory.
    let loadDirectory (directory: string) =
        Directory.EnumerateFiles(directory, "*.json") |> loadMany

    /// Small projection that is useful when indexing a folder of programs.
    let summary (program: CoveredBondProgram.Root) =
        {|
            IssuerName = program.IssuerName
            ProgramName = program.ProgramName
            BondCount = program.Bonds.Length
            MinimumAssetPercentage = program.MinimumAssetPercentage
            MaximumAssetPercentage = program.MaximumAssetPercentage
        |}
